query OrgRuns($org: String!, $appId: Int!, $cursor: String) {
  organization(login: $org) {
    repositories(first: 25, after: $cursor, orderBy: {field: PUSHED_AT, direction: DESC}) {
      pageInfo { hasNextPage endCursor }
      nodes {
        name
        defaultBranchRef {
          target {
            ... on Commit {
              history(first: 5) {
                nodes {
                  checkSuites(first: 3, filterBy: {appId: $appId}) {
                    nodes {
                      status
                      conclusion
                      workflowRun {
                        databaseId
                        url
                        createdAt
                        workflow { name }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

